const POKEDEX = {};
POKEDEX_DATA.forEach(p => { POKEDEX[p.name] = p; });
function getPokemon(name) { return POKEDEX[name] || null; }

// Sprite URLs: your Custom Sprite first, else official artwork (shiny folder for shinies).
// HOME renders are the fallback (use spriteFallbackUrl in an <img onerror>).
const SPRITE_BASE = 'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon/other/';
function spriteUrl(p, shiny) {
  if (!p) return null;
  if (p.customSprite) return p.customSprite;
  if (!p.spriteId) return null;
  return SPRITE_BASE + 'official-artwork/' + (shiny ? 'shiny/' : '') + p.spriteId + '.png';
}
function spriteFallbackUrl(p, shiny) {
  if (!p || !p.spriteId) return null;
  return SPRITE_BASE + 'home/' + (shiny ? 'shiny/' : '') + p.spriteId + '.png';
}
